    // Penalize creating bins with too much unused space
    if post_residual > 50 {
        score -= (post_residual - 50) as f64;
    }

    // Reward filling bins more efficiently
    if bin_residual >= item_size {
        score += (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    }

    // Penalize creating small gaps that may not fit the next item
    if fitting_bins_count == 0 && next_item_size != 0 {
        score -= next_item_size as f64 / bin_capacity as f64;
    }

    // Reward using open bins with higher residual space
    if mean_residual > post_residual {
        score += (mean_residual - post_residual) as f64;
    }

    // Penalize opening new bins unnecessarily
    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating bins with too much unused space
    if post_residual > 50 {
        score -= (post_residual - 50) as f64 * 1.2;
    }

    // Reward filling bins more efficiently
    if bin_residual >= item_size {
        score += ((bin_capacity - post_residual) as f64 / bin_capacity as f64).powi(2);
    }

    // Penalize creating small gaps that may not fit the next item
    if fitting_bins_count == 0 && next_item_size != 0 {
        score -= (next_item_size as f64 / bin_capacity as f64) * 1.5;
    }

    // Reward using open bins with higher residual space
    if mean_residual > post_residual {
        score += (mean_residual - post_residual) as f64 * 1.1;
    }

    // Penalize opening new bins unnecessarily
    score -= 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Favor bins with more space
    if bin_residual > item_size {
        score += (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 1.8;
    }

    // Penalize creating new bins
    if open_bins_count == 0 {
        score -= 2.5;
    } else if fitting_bins_count == 0 {
        score -= 0.75 * (open_bins_count as f64).log2();
    }

    // Reward using smaller bins for better packing efficiency
    let ideal_bin_size = 65.0; // Adjusted ideal bin size
    if item_size < ideal_bin_size {
        score += (ideal_bin_size - item_size as f64) / ideal_bin_size * 1.3;
    }

    // Penalize leaving large spaces in bins
    if post_residual > 20.0 {
        score -= post_residual as f64 / bin_capacity as f64 * 3.0;
    }

    // Reward using bins with a mean residual close to the current item size
    let ideal_mean_residual = item_size as f64;
    if (mean_residual - ideal_mean_residual).abs() < 5.0 {
        score += 1.2 - ((mean_residual - ideal_mean_residual).abs() / 5.0) * 1.8;
    }

    // Penalize lookahead items that don't fit in any bin
    if next_item_size > 0 && fitting_bins_count == 0 {
        score -= next_item_size as f64 / bin_capacity as f64 * 3.0;
    }

    // Reward using bins with a better time horizon for future items
    let lookahead_ratio = (step_index + 1) as f64 / total_items as f64;
    if lookahead_ratio < 0.5 {
        score += 1.2 - lookahead_ratio * 3.5;
    } else {
        score -= lookahead_ratio * 4.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize
) -> f64 {
    let stream_progress = step_index as f64 / total_items as f64;
    let normalized_post_residual = post_residual as f64 / bin_capacity as f64;

    let mut score = -10.0 * normalized_post_residual.powi(2) + 5.0 * stream_progress;

    if (post_residual - mean_residual).abs() < 5.0 {
        score += 0.2;
    }

    if post_residual < next_item_size {
        score -= 1.0;
    }

    // Lookahead trade-off
    let lookahead_factor = 0.5;
    if fitting_bins_count > 0 {
        score += lookahead_factor * (fitting_bins_count as f64 / open_bins_count as f64);
    }

    score
}
